// Writes index.html: the standalone page (open it directly, or host it anywhere) with the
// browser bundle inlined, so it keeps working as a single file. Run via `npm run build`.
import { readFileSync, writeFileSync } from "node:fs";

const bundle = readFileSync(new URL("../dist/packing-bingo.global.js", import.meta.url), "utf8").replace(/<\/script/gi, "<\\/script");

const html = `<!doctype html>
<!-- Generated by scripts/build-standalone.mjs from src/. Edit src/ and run \`npm run build\`. -->
<html lang="ja">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>持ちものビンゴ</title>
<style>body{margin:0;padding:12px}</style>
</head>
<body>
<div id="app"></div>
<script>${bundle}</script>
<script>
// ?demo: start part-way through and show the demo buttons. Otherwise progress is saved in this browser.
var demo = new URLSearchParams(location.search).has("demo");
PackingBingo.createPackingBingo(document.getElementById("app"), { demo: demo, storageKey: demo ? null : "packing-bingo" });
</script>
</body>
</html>
`;

writeFileSync(new URL("../index.html", import.meta.url), html);
console.log(`index.html written (${Math.round(html.length / 1024)} KB)`);
